11	interface Props {
12	  requisicaoId: number;
13	  open: boolean;
14	  onClose: () => void;
15	}
16	
17	interface SaidaItem {
18	  etiqueta_uid: string;
19	  usuario_nome: string | null;
20	  metadata: {
21	    lote_id?: string;
22	    quantidade?: number;
23	    saldo_anterior?: number;
24	    saldo_novo?: number;
25	  };
26	  created_at: string;
27	  produto_nome_snapshot: string | null;
28	}
29	
30	export function SaidaRequisicaoResumoDialog({ requisicaoId, open, onClose }: Props) {
31	  const { data: itens, isLoading } = useQuery<SaidaItem[]>({
32	    queryKey: ['saida-requisicao-eventos', requisicaoId],
33	    enabled: open && requisicaoId > 0,
34	    queryFn: async () => {
35	      // 1. Fetch events
36	      const { data: eventos, error: eventosError } = await (supabase.from('etiquetas_qr_eventos') as any)
37	        .select('etiqueta_uid, usuario_nome, metadata, created_at')
38	        .eq('tipo_evento', 'saida_requisicao')
39	        .eq('referencia_tipo', 'requisicao')
40	        .eq('referencia_id', String(requisicaoId));
41	
42	      if (eventosError) throw eventosError;
43	
44	      if (!eventos || eventos.length === 0) {
45	        return [];
46	      }
47	
48	      const uids = [...new Set(eventos.map((e: any) => e.etiqueta_uid as string))];
49	
50	      // 2. Fetch tags
51	      const { data: tags, error: tagsError } = await (supabase.from('etiquetas_qr') as any)
52	        .select('uid, produto_nome_snapshot')
53	        .in('uid', uids);
54	
55	      if (tagsError) throw tagsError;
56	
57	      const tagsMap = new Map<string, string | null>(
58	        (tags || []).map((t: any) => [t.uid as string, t.produto_nome_snapshot as string | null])
59	      );
60	
61	      // 3. Join
62	      return eventos.map((e: any) => ({
63	        etiqueta_uid: e.etiqueta_uid as string,
64	        usuario_nome: e.usuario_nome as string | null,
65	        metadata: (e.metadata || {}) as SaidaItem['metadata'],
66	        created_at: e.created_at as string,
67	        produto_nome_snapshot: tagsMap.get(e.etiqueta_uid as string) ?? null,
68	      })) as SaidaItem[];
69	    }
70	  });
71	
72	  const totalItens = itens?.length || 0;
73	  const totalQuantidade = itens?.reduce((acc, curr) => acc + (curr.metadata?.quantidade || 0), 0) || 0;
74	
75	  return (
76	    <Dialog open={open} onOpenChange={(val) => !val && onClose()}>
77	      <DialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl max-w-2xl p-0 overflow-hidden">
78	        <DialogHeader className="p-6 pb-4 border-b border-[#57715B]/10">
79	          <div className="flex items-center gap-3">
80	            <div className="h-10 w-10 rounded-xl bg-[#57715B]/10 flex items-center justify-center">
81	              <PackageCheck className="h-5 w-5 text-[#57715B]" />
82	            </div>
83	            <DialogTitle className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
84	              Saída por Requisição #{requisicaoId}
85	            </DialogTitle>
86	          </div>
87	        </DialogHeader>
88	
89	        <div className="p-6">
90	          {isLoading ? (
91	            <div className="space-y-3">
92	              <Skeleton className="h-10 w-full rounded-xl bg-[#57715B]/5" />
93	              <Skeleton className="h-10 w-full rounded-xl bg-[#57715B]/5" />
94	              <Skeleton className="h-10 w-full rounded-xl bg-[#57715B]/5" />
95	            </div>
96	          ) : !itens || itens.length === 0 ? (
97	            <div className="flex flex-col items-center justify-center py-12 text-center">
98	              <div className="h-16 w-16 rounded-full bg-[#57715B]/5 flex items-center justify-center mb-4">
99	                <PackageX className="h-8 w-8 text-[#57715B]/40" />
100	              </div>
101	              <h3 className="text-lg font-medium text-[#2D362E] dark:text-[#E6DCCF]">Nenhuma saída registrada</h3>
102	              <p className="text-sm text-muted-foreground mt-1">
103	                Nenhuma saída foi registrada para esta requisição.
104	              </p>
105	            </div>
106	          ) : (
107	            <div className="space-y-4">
108	              {/* Summary Bar */}
109	              <div className="flex items-center gap-4 p-4 rounded-xl bg-[#57715B]/5 border border-[#57715B]/10">
110	                <div>
111	                  <div className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Total de Itens</div>
112	                  <div className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">{totalItens}</div>
113	                </div>
114	                <div className="w-px h-8 bg-[#57715B]/10" />
115	                <div>
116	                  <div className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Quantidade Total</div>
117	                  <div className="text-lg font-bold text-[#57715B]">{totalQuantidade}</div>
118	                </div>
119	              </div>
120	
121	              {/* Table */}
122	              <div className="rounded-xl border border-[#57715B]/10 overflow-hidden">
123	                <div className="overflow-x-auto">
124	                  <Table>
125	                    <TableHeader className="bg-[#57715B]/5 border-b border-[#57715B]/10">
126	                      <TableRow className="hover:bg-transparent">
127	                        <TableHead className="font-semibold text-[#57715B]">Produto</TableHead>
128	                        <TableHead className="font-semibold text-[#57715B]">Lote</TableHead>
129	                        <TableHead className="font-semibold text-[#57715B] text-center">Qtd</TableHead>
130	                        <TableHead className="font-semibold text-[#57715B]">Operador</TableHead>
131	                        <TableHead className="font-semibold text-[#57715B] text-right">Horário</TableHead>
132	                      </TableRow>
133	                    </TableHeader>
134	                    <TableBody>
135	                      {itens.map((item, idx) => (
136	                        <TableRow
137	                          key={`${item.etiqueta_uid}-${idx}`}
138	                          className="hover:bg-[#57715B]/5 border-b border-[#57715B]/5 last:border-0 transition-colors"
139	                        >
140	                          <TableCell className="font-medium text-[#2D362E] dark:text-[#E6DCCF]">
141	                            {item.produto_nome_snapshot || 'Produto Desconhecido'}
142	                          </TableCell>
143	                          <TableCell>
144	                            {item.metadata?.lote_id ? (
145	                              <span className="font-mono text-xs text-muted-foreground bg-white/50 dark:bg-black/20 px-2 py-1 rounded-lg border border-[#57715B]/10">
146	                                {item.metadata.lote_id.substring(0, 8)}
147	                              </span>
148	                            ) : (
149	                              <span className="text-xs text-muted-foreground italic">N/A</span>
150	                            )}
151	                          </TableCell>
152	                          <TableCell className="text-center font-bold text-[#2D362E] dark:text-[#E6DCCF]">
153	                            {item.metadata?.quantidade ?? 0}
154	                          </TableCell>
155	                          <TableCell className="text-sm text-muted-foreground">
156	                            {item.usuario_nome || 'Desconhecido'}
157	                          </TableCell>
158	                          <TableCell className="text-right font-mono text-xs text-muted-foreground">
159	                            {format(new Date(item.created_at), 'dd/MM HH:mm', { locale: ptBR })}
160	                          </TableCell>
161	                        </TableRow>
162	                      ))}
163	                    </TableBody>
164	                  </Table>
165	                </div>
166	              </div>
167	            </div>
168	          )}
169	        </div>
170	
171	        <div className="p-4 border-t border-[#57715B]/10 flex justify-end bg-white/50 dark:bg-black/20">
172	          <Button variant="ghost" onClick={onClose} className="text-[#57715B] hover:bg-[#57715B]/10">
173	            Fechar
174	          </Button>
175	        </div>
176	      </DialogContent>
177	    </Dialog>
178	  );
179	}
