144	const makeChainable = (table: string) => {
145	  const c: Record<string, ReturnType<typeof vi.fn> | ((resolve: (v: { data: unknown; error: null }) => void) => unknown)> = {
146	    select: vi.fn(() => c),
147	    eq: vi.fn(() => c),
148	    order: vi.fn(() => c),
149	    limit: vi.fn(() => c),
150	    in: vi.fn(() => c),
151	    not: vi.fn(() => c),
152	    ilike: vi.fn(() => c),
153	    or: vi.fn(() => c),
154	    gt: vi.fn(() => c),
155	    gte: vi.fn(() => c),
156	    lte: vi.fn(() => c),
157	    update: vi.fn(() => c),
158	    insert: vi.fn(() => c),
159	    delete: vi.fn(() => c),
160	    maybeSingle: vi.fn(() => Promise.resolve({ data: null, error: null })),
161	    single: vi.fn(() =>
162	      Promise.resolve({
163	        data: table === 'requisicoes' ? mockReqInfo : mockItensColetados[0],
164	        error: null,
165	      }),
166	    ),
167	    then: (resolve: (v: { data: unknown; error: null }) => void) => {
168	      if (table === 'requisicoes')
169	        return resolve({ data: mockReqInfo, error: null });
170	      if (table === 'requisicoes_itens')
171	        return resolve({ data: mockItensColetados, error: null });
172	      if (table === 'profiles')
173	        return resolve({
174	          data: { nome: 'Operador Teste', username: 'operador' },
175	          error: null,
176	        });
177	      return resolve({ data: [], error: null });
178	    },
179	  };
180	  return c;
181	};
182	
183	/** Configura supabase.from + channel + rpc conforme cenário. */
184	const setupSupabaseMock = ({
185	  rpcResult,
186	}: {
187	  rpcResult: { data: unknown; error: null | { message: string } };
188	}) => {
189	  (supabase.from as ReturnType<typeof vi.fn>).mockImplementation((table: string) => {
190	    const c = makeChainable(table);
191	    // UPDATE atômico de status: retornar 1 row para simular sucesso de reserva.
192	    if (table === 'requisicoes') {
193	      c.update = vi.fn(() => {
194	        const upChain = { ...c };
195	        upChain.eq = vi.fn(() => upChain);
196	        upChain.select = vi.fn(() =>
197	          Promise.resolve({ data: [{ id: 123 }], error: null }),
198	        );
199	        return upChain;
200	      });
201	    }
202	    return c;
203	  });
204	  (supabase.channel as ReturnType<typeof vi.fn>).mockReturnValue(mockChannel);
205	  (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValue(rpcResult);
206	};
207	
208	const renderComponent = () =>
209	  render(
210	    <BrowserRouter>
211	      <PaginaPicking />
212	    </BrowserRouter>,
213	  );
214	
215	/** Aguarda o carregamento inicial do componente. */
216	const waitForLoad = () =>
217	  waitFor(() => expect(screen.getByText('Brownie')).toBeInTheDocument(), {
218	    timeout: 5000,
219	  });
220	
221	/** Clica no botão Finalizar (habilitado). */
222	const clickFinalizar = async () => {
223	  const btn = screen.queryByRole('button', { name: /finalizar/i });
224	  if (!btn) throw new Error('Botão Finalizar não encontrado');
225	  await act(async () => {
226	    fireEvent.click(btn);
227	  });
228	};
229	
230	// ── suíte ───────────────────────────────────────────────────────────────────
231	
232	describe('finalizarPicking() — integração dar_saida_requisicao', () => {
233	  beforeEach(() => {
234	    vi.clearAllMocks();
235	    (routerDom.useParams as ReturnType<typeof vi.fn>).mockReturnValue({ requisicaoId: '123' });
236	    (routerDom.useNavigate as ReturnType<typeof vi.fn>).mockReturnValue(mockNavigate);
237	  });
238	
239	  it('1. chama dar_saida_requisicao e abre dialog de resumo (navigate NÃO é chamado imediatamente)', async () => {
240	    setupSupabaseMock({
241	      rpcResult: {
242	        data: { ok: true, requisicao_id: 123, etiquetas_processadas: 3, total_quantidade: 9, ja_processadas: 0, alertas: [] },
243	        error: null,
244	      },
245	    });
246	
247	    renderComponent();
248	    await waitForLoad();
249	    await clickFinalizar();
250	
251	    // RPC deve ter sido chamada com o id correto
252	    await waitFor(() => {
253	      expect(supabase.rpc).toHaveBeenCalledWith('dar_saida_requisicao', {
254	        p_requisicao_id: 123,
255	      });
256	    });
257	
258	    // Dialog de resumo deve abrir em vez de navegar imediatamente
259	    await waitFor(() => {
260	      expect(screen.getByTestId('resumo-saida-dialog')).toBeInTheDocument();
261	    });
262	
263	    // navigate NÃO deve ter sido chamado ainda (só acontece ao fechar o dialog)
264	    expect(mockNavigate).not.toHaveBeenCalledWith('/logistica');
265	  });
266	
267	  it('2. exibe toast de warning quando alertas é não-vazio', async () => {
268	    setupSupabaseMock({
269	      rpcResult: {
270	        data: {
271	          ok: true,
272	          requisicao_id: 123,
273	          etiquetas_processadas: 2,
274	          total_quantidade: 4,
275	          ja_processadas: 0,
276	          alertas: [{ uid: 'abc', motivo: 'saldo_insuficiente' }],
277	        },
278	        error: null,
279	      },
280	    });
281	
282	    renderComponent();
283	    await waitForLoad();
284	    await clickFinalizar();
285	
286	    await waitFor(() => {
287	      // Deve ter chamado toast de sucesso E toast de warning (destructive)
288	      const toastCalls = mockToast.mock.calls;
289	      const warningCall = toastCalls.find(
290	        ([arg]: [{ variant?: string; title?: string }]) => arg?.variant === 'destructive' && /saldo insuficiente/i.test(arg?.description ?? ''),
291	      );
292	      expect(warningCall).toBeDefined();
293	    });
294	  });
295	
296	  it('3. quando RPC falha, status reverte para em_progresso e navigate NÃO é chamado', async () => {
297	    setupSupabaseMock({
298	      rpcResult: {
299	        data: null,
300	        error: { message: 'connection timeout' },
301	      },
302	    });
303	
304	    renderComponent();
305	    await waitForLoad();
306	    await clickFinalizar();
307	
308	    await waitFor(() => {
309	      // navigate('/logistica') NÃO deve ter sido chamado
310	      expect(mockNavigate).not.toHaveBeenCalledWith('/logistica');
311	    });
312	
313	    // O UPDATE de rollback (em_progresso) deve ter sido tentado
314	    await waitFor(() => {
315	      // supabase.from('requisicoes').update() é chamado duas vezes:
316	      //   1ª: reserva → status='finalizada'
317	      //   2ª: rollback → status='em_progresso'
318	      const fromCalls = (supabase.from as ReturnType<typeof vi.fn>).mock.calls;
319	      const reqCalls = fromCalls.filter((args) => args[0] === 'requisicoes');
320	      expect(reqCalls.length).toBeGreaterThanOrEqual(2);
321	    });
322	  });
323	});
324

1937	  const finalizarPicking = async () => {
1938	    if (finalizando) return; // Guard local contra duplo-clique
1939	    if (!requisicaoId) return;
1940	
1941	    const itensNaoColetados = itens.filter(
1942	      (item) => !(String(item.quantidade_enviada || '').trim() !== ''),
1943	    );
1944	    if (itensNaoColetados.length > 0) {
1945	      toast({
1946	        title: 'Atenção',
1947	        description: `Ainda há ${itensNaoColetados.length} itens não coletados.`,
1948	        variant: 'destructive',
1949	      });
1950	      return;
1951	    }
1952	
1953	    let statusReserved = false;
1954	    try {
1955	      setFinalizando(true);
1956	
1957	      // === GUARD DE RACE CONDITION ===
1958	      // Estratégia: fazer o UPDATE atômico em_progresso -> finalizada ANTES de deduzir estoque.
1959	      // O PostgreSQL serializa UPDATEs concorrentes na mesma linha, então apenas uma sessão
1960	      // conseguirá afetar a linha; as demais receberão 0 rows e abortarão.
1961	      // Se a dedução posterior falhar, revertemos o status no bloco catch.
1962	      const { data: reserveData, error: reserveError } = await supabase
1963	        .from('requisicoes' as any)
1964	        .update({ status: 'finalizada' })
1965	        .eq('id', requisicaoId)
1966	        .eq('status', 'em_progresso')
1967	        .select('id');
1968	
1969	      if (reserveError) throw reserveError;
1970	
1971	      const affected =
1972	        reserveData && Array.isArray(reserveData) ? reserveData.length : 0;
1973	
1974	      if (affected === 0) {
1975	        // Outra sessão já finalizou, ou o status não era 'em_progresso'.
1976	        // Verifica o status atual para dar feedback preciso.
1977	        const { data: currentReq } = await supabase
1978	          .from('requisicoes' as any)
1979	          .select('status')
1980	          .eq('id', requisicaoId)
1981	          .single();
1982	
1983	        const currentStatus = (currentReq as { status?: string } | null)?.status;
1984	        const normalizedCurrent = normalizeRequisicaoStatus(currentStatus);
1985	
1986	        if (normalizedCurrent === 'finalizada') {
1987	          toast({
1988	            title: 'Já finalizada',
1989	            description: 'Esta requisição já foi finalizada por outra sessão.',
1990	            variant: 'destructive',
1991	          });
